\begin{theorem}\label{thm:groupclt_split_block}
 Assume that
\begin{itemize} 
\item[(i)] $\sigma \kappa^\frac{23}{4} \mu^\frac{3}{2} r^\frac{3}{2} \min\{\sqrt{N_0},\sqrt{|\calG| T_0}\} \max\{{N_0\sqrt{\log{N_0}}},{T_0\sqrt{\log{T_0}}}\}=o_p\left(\psi_{\min,O} \min\{N_0,T_0\}\right)$;
\item[(ii)] $\kappa^\frac{11}{2} \mu^{3} r^{3} \min\{\sqrt{N_0},\sqrt{|\calG| T_0}\} \max\{{\sqrt{N_0\log^3{N_0}}},{\sqrt{T_0\log^3{T_0}}}\}=o_p\left( \min\{N_0^\frac{3}{2},T_0^\frac{3}{2}\}\right)$;
\item[(iii)] $|\calG_l| \kappa^\frac{17}{4} \mu^\frac{5}{2} r^\frac{5}{2} \max\{\sqrt{N_0\log{N_0}},\sqrt{T_0\log{T_0}}\}=o_p\left(\sqrt{N_0} \min\{N_0,T_0\}\right)$, $l=1,\ldots, L$;
\item[(iv)] There are constants $C,c > 0 $ such that
        \begin{align*}
             &c \leq \lambda_{\min} \left( \frac{N}{N_0} \sum_{i \leq N_0} u_{i}u_{i}^\top  \right) \leq  \lambda_{\max} \left( \frac{N}{N_0} \sum_{i \leq N_0} u_{i}u_{i}^\top  \right) \leq C, \\
             &c \leq \lambda_{\min} \left( \frac{T}{T_0} \sum_{t \leq T_0 } v_{t}v_{t}^\top  \right) \leq \lambda_{\max} \left( \frac{T}{T_0} \sum_{t \leq T_0 } v_{t}v_{t}^\top  \right) \leq C;
        \end{align*}
\item[(v)] $\sqrt{N}\norm{\bar{u}_{\calG}} \geq c$ and $\sqrt{T}\norm{v_{t_0}} \geq c$ for some constant $c>0$ where $\bar{u}_{\calG} = |\calG|^{-1}\sum_{i \in \calG} u_{i}$.
\end{itemize}
Then, we have
  \begin{gather*}
    \mathcal{V}_{\mathcal{G}}^{-\frac{1}{2}}\left( \frac{1}{|\mathcal{G}|}\sum_{ i \in \mathcal{G}}\widehat{m}_{it_0} -   \frac{1}{|\mathcal{G}|}\sum_{ i \in \mathcal{G}}m_{it_0} \right) \overset{D}{\longrightarrow} \mathcal{N}(0,1),
  \end{gather*}
where
  $$
\mathcal{V}_{\mathcal{G}}=
  \sigma^2 \left( \bar{u}_{\calG}^\top\left( \sum_{j\le N_0} u_j u_j^\top\right)^{-1}\bar{u}_{\calG}
  + \frac{1}{|\calG|}v_{t_0}^\top\left( \sum_{s \leq T_0} v_s v_s^\top\right)^{-1}v_{t_0} \right).
  $$   
\end{theorem}
